import { SearchIcon } from '@ho-dev/icons';
import { Button } from '@ho-dev/primitives';

/**
 * The icon is decorative by default (it renders `aria-hidden`), so the control
 * takes its accessible name from the button label.
 */
export function SearchAction() {
  return <Button aria-label="Search the catalogue" icon={<SearchIcon />} />;
}

import { Button } from '@ho-dev/primitives';
import { cn } from '@ho-dev/utils';

/**
 * Applications import the public entry point of every package. A dependency
 * belongs to the package whose source imports it, never to the application.
 */
export function SubmitRow({ busy }: { busy: boolean }) {
  return (
    <div className={cn('flex items-center gap-3', busy && 'opacity-60')}>
      <Button type="submit">Save</Button>
    </div>
  );
}

import { AreaChart, type ChartSeries } from '@ho-dev/charts';

/** The package already renders the chart lazily, behind a skeleton. */
const series: ChartSeries[] = [
  {
    name: 'Revenue',
    data: [
      { x: 'Jan', y: 4000 },
      { x: 'Feb', y: 3000 },
    ],
  },
];

export function RevenueChart() {
  return (
    <AreaChart
      series={series}
      height={350}
      label="Monthly revenue"
      description="Revenue for January and February."
    />
  );
}

import { Field, Form, Submit } from '@ho-dev/forms';

/** Field owns the label, the description, the error message and their ARIA links. */
export function NewsletterForm() {
  return (
    <Form
      onSubmit={(event) => {
        const data = new FormData(event.currentTarget);
        console.log(Object.fromEntries(data.entries()));
      }}
    >
      <Field label="Email" description="We only use it to send the newsletter.">
        <input type="email" name="email" autoComplete="email" required />
      </Field>
      <Submit>Subscribe</Submit>
    </Form>
  );
}

import { Button } from '@ho-dev/primitives';

/** The smallest consumer: one package, one component. */
export function GettingStartedExample() {
  return <Button>Save changes</Button>;
}

import { IconWrapper, SearchIcon } from '@ho-dev/icons';

/** Icons follow `currentColor` and size; `title` gives a decorative icon meaning. */
export function SearchFieldIcon() {
  return (
    <div className="text-dark-4 dark:text-dark-6 flex items-center gap-2">
      <SearchIcon className="h-5 w-5" />
      <IconWrapper title="Status: available" size={20} viewBox="0 0 24 24">
        <circle cx="12" cy="12" r="6" fill="currentColor" />
      </IconWrapper>
    </div>
  );
}

import { Button } from '@ho-dev/primitives';
import { ThemeProvider } from '@ho-dev/theme';

/** Two installed packages: a foundation provider and a component. */
export function InstallationCheck() {
  return (
    <ThemeProvider>
      <Button>Installed</Button>
    </ThemeProvider>
  );
}

import { Header, HeaderActions, HeaderToggle, Sidebar, SidebarProvider } from '@ho-dev/layouts';

import type { ReactNode } from 'react';

/** The shell owns open/close state; the application owns what goes inside. */
export function AppLayout({
  children,
  navigation,
}: {
  children: ReactNode;
  navigation: ReactNode;
}) {
  return (
    <SidebarProvider>
      <Header>
        <HeaderToggle />
        <HeaderActions>
          <span className="text-sm">Signed in</span>
        </HeaderActions>
      </Header>
      <Sidebar logo={<span className="text-sm font-semibold">Holiveira</span>}>
        <nav aria-label="Main navigation">{navigation}</nav>
      </Sidebar>
      <main>{children}</main>
    </SidebarProvider>
  );
}

import { SidebarProvider } from '@ho-dev/layouts';
import { ProviderComposer, type ProviderTree } from '@ho-dev/providers';
import { ThemeProvider } from '@ho-dev/theme';

import type { ReactNode } from 'react';

/** Outermost first: the theme wraps the layout, the layout wraps the application. */
const tree: ProviderTree = [[ThemeProvider], [SidebarProvider]];

export function AppProviders({ children }: { children: ReactNode }) {
  return <ProviderComposer tree={tree}>{children}</ProviderComposer>;
}

import { cn, cva, type VariantProps } from '@ho-dev/utils';

/** Variants live beside the component and merge through `cn`. */
const badge = cva('inline-flex items-center rounded-full px-2 py-1 text-xs', {
  variants: {
    tone: {
      neutral: 'bg-gray-2 text-dark-4 dark:bg-dark-2 dark:text-dark-6',
      primary: 'bg-primary text-white',
    },
  },
  defaultVariants: { tone: 'neutral' },
});

type BadgeStyleProps = VariantProps<typeof badge>;

export function badgeClassName({ tone, className }: BadgeStyleProps & { className?: string }) {
  return cn(badge({ tone }), className);
}

'use client';

import { ThemeProvider, useTheme } from '@ho-dev/theme';

/** Reads the active theme and writes the next one. */
export function ThemeToggle() {
  const { theme, setTheme } = useTheme();

  return (
    <button type="button" onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}>
      Switch to the {theme === 'dark' ? 'light' : 'dark'} theme
    </button>
  );
}

/** The provider wraps the application once, above anything that reads the theme. */
export function ThemedApp() {
  return (
    <ThemeProvider>
      <ThemeToggle />
    </ThemeProvider>
  );
}

import { colors, containers } from '@ho-dev/tokens';

/** The TypeScript objects mirror the CSS custom properties they generate. */
export const primaryColor = colors.primary;

/** CSS escapes resolve in the key: `--container-2_5` is `containers['2_5']`. */
export const cardRadius = containers['2_5'];
